INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (3.099, "2022/04/18 15:00:00", 1, 2, 2, "2030/01/01 14:59:59", 0, "ミッションをクリアして、\n報酬をゲットしましょう！", 53, 190801, -416.5, 20026, 20026002, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (2.801, "2022/04/18 15:00:00", 1, 3, 2, "2030/01/01 14:59:59", 0, "受け取ることができる\n報酬があるようです\n確認してみてください", 54, 190801, -416.5, 20026, 20026003, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (0, "2022/04/18 15:00:00", 2, 4, 2, "2030/01/01 14:59:59", 0, "報酬がもらえますよ！\nチェックしてみてください", 54, 190801, -416.5, 20026, 20026004, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (0, "2022/04/18 15:00:00", 1, 5, 1, "2030/01/01 14:59:59", 0, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています", 57, 190801, -416.5, 20026, 20026005, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (5.506, "2022/04/18 15:00:00", 1, 1, 2, "2030/01/01 14:59:59", 0, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ", 55, 190801, -363, 20026, 20026006, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (1.216, "2022/04/18 15:00:00", 2, 2, 1, "2030/01/01 14:59:59", 0, "お疲れ様です！\nここでは、討伐証と報酬を\n交換することができます！", 55, 190801, -363, 20026, 20026007, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (1.539, "2022/04/18 15:00:00", 2, 3, 1, "2030/01/01 14:59:59", 0, "お疲れ様でした\n討伐証の交換、\nお忘れないように！", 56, 190801, -363, 20026, 20026008, "カリン");
INSERT INTO `v1_6d90df249f48fd2af21c8358859a3d7b837ef1584fda8a8ad35ec1940e99c198` VALUES (1.875, "2022/04/18 15:00:00", 2, 4, 1, "2030/01/01 14:59:59", 0, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！", 56, 190801, -363, 20026, 20026009, "カリン");
